<?php
require __DIR__.'/bootstrap.php'; require_auth(); if(!can('products.view')){http_response_code(403);exit('Forbidden');} require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST' && can('products.manage')){verify_csrf();$id=(int)($_POST['id']??0);$data=[trim($_POST['item_code']),trim($_POST['name']),$_POST['barcode']?:null,$_POST['brand_id']?:null,$_POST['category_id']?:null,trim($_POST['model']),trim($_POST['unit']),$_POST['avg_cost'],$_POST['retail_price'],$_POST['wholesale_price'],$_POST['minimum_stock'],(int)isset($_POST['serial_tracking']),$_POST['warranty_months'],trim($_POST['rack_location'])];if($id){$old=$db->query('SELECT * FROM products WHERE id='.$id)->fetch();$stmt=$db->prepare('UPDATE products SET item_code=?,name=?,barcode=?,brand_id=?,category_id=?,model=?,unit=?,avg_cost=?,retail_price=?,wholesale_price=?,minimum_stock=?,serial_tracking=?,warranty_months=?,rack_location=? WHERE id=?');$stmt->execute([...$data,$id]);audit($db,'update','product',$id,$old,$data);}else{$stmt=$db->prepare('INSERT INTO products(item_code,name,barcode,brand_id,category_id,model,unit,avg_cost,retail_price,wholesale_price,minimum_stock,serial_tracking,warranty_months,rack_location) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute($data);$id=(int)$db->lastInsertId();audit($db,'create','product',$id,null,$data);}flash('success','Product saved successfully.');redirect('products.php');}
$q=trim($_GET['q']??'');$stmt=$db->prepare('SELECT p.*,b.name brand,c.name category FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.status="active" AND (p.name LIKE ? OR p.item_code LIKE ? OR p.barcode LIKE ?) ORDER BY p.id DESC');$like="%$q%";$stmt->execute([$like,$like,$like]);$rows=$stmt->fetchAll();$brands=$db->query('SELECT * FROM brands WHERE status="active" ORDER BY name')->fetchAll();$categories=$db->query('SELECT * FROM categories WHERE status="active" ORDER BY name')->fetchAll();page_start('Products','products.php');?>
<div class="toolbar"><form><input name="q" value="<?=e($q)?>" placeholder="Search code, name or barcode"><button class="btn secondary">Search</button></form><?php if(can('products.manage')):?><button class="btn primary" onclick="document.getElementById('product-form').scrollIntoView()">＋ Add product</button><?php endif;?></div><div class="page-grid"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Catalogue</span><h3><?=count($rows)?> active products</h3></div></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Stock</th><?php if(user()['role_code']!=='cashier'):?><th>Avg cost</th><?php endif;?><th>Retail</th><th>Wholesale</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['item_code'])?></b><br><span class="muted"><?=e($r['name'])?></span></td><td><?=e($r['category']??'—')?> · <?=e($r['brand']??'—')?></td><td><span class="status <?=$r['current_stock']<=$r['minimum_stock']?'overdue':'active'?>"><?=e($r['current_stock'])?> <?=e($r['unit'])?></span></td><?php if(user()['role_code']!=='cashier'):?><td><?=money($r['avg_cost'])?></td><?php endif;?><td><?=money($r['retail_price'])?></td><td><?=money($r['wholesale_price'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(can('products.manage')):?><aside class="panel" id="product-form"><div class="panel-head"><div><span class="eyebrow">Product master</span><h3>Add a product</h3></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf()?>"><label>Item code<input name="item_code" required></label><label>Barcode<input name="barcode"></label><label class="full">Product name<input name="name" required></label><label>Brand<select name="brand_id"><option value="">Select</option><?php foreach($brands as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label>Category<select name="category_id"><option value="">Select</option><?php foreach($categories as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label>Model<input name="model"></label><label>Unit<input name="unit" value="PCS"></label><label>Cost price<input type="number" step=".01" min="0" name="avg_cost" value="0"></label><label>Retail price<input type="number" step=".01" min="0" name="retail_price" required></label><label>Wholesale price<input type="number" step=".01" min="0" name="wholesale_price" required></label><label>Minimum stock<input type="number" step=".001" min="0" name="minimum_stock" value="0"></label><label>Warranty months<input type="number" min="0" name="warranty_months" value="0"></label><label>Rack / location<input name="rack_location"></label><label class="full"><span><input type="checkbox" name="serial_tracking"> Track individual serial numbers</span></label><button class="btn primary full">Save product</button></form></aside><?php endif;?></div><?php page_end();

